/**
 * name: probe_vendor_size
 * description: Discovery probe - will the Affinity Script Manager import and run a ~400KB script file (the size of a vendored planck.js + poly-decomp)?
 * version: 0.1.0
 * author: ollio
 *
 * USAGE: no selection needed, no document needed. Import it, run it, copy the CONSOLE output.
 * READ-ONLY: never touches the document.
 *
 * This file is deliberately padded to ~433KB with 4166 small real functions -
 * roughly the parse load of planck.js (~200KB min) + poly-decomp (~30KB) with
 * headroom. Three separate things can fail, and this tells them apart:
 *
 *   A. Script Manager / MCP save_script_to_library rejects or truncates it
 *      -> the script never appears in the panel, or appears and throws on load.
 *   B. The sandbox parser chokes or is unusably slow
 *      -> PARSE line below never prints.
 *   C. It all works
 *      -> you get the SIZE / PARSE / CALL lines and "probe done".
 *
 * If it works, vendoring a real engine inline is viable and we take that route.
 * If it fails, we fall back to a tree-shaken subset or a hand-rolled solver.
 */

